css:
.sl-feature-typo {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-typo h2,
.sl-feature-typo h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-typo .sl-text-primary { color: var(--smartlearn-primary); }
.sl-feature-typo .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-typo .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-typo .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-typo .sl-eyebrow { letter-spacing: 0.1em; }
.sl-feature-typo .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-typo .sl-typo-row {
    border-bottom-color: var(--smartlearn-card-border);
}
.sl-feature-typo .sl-typo-row:first-child {
    border-top-color: var(--smartlearn-card-border);
}
.sl-feature-typo .sl-row-link {
    color: inherit;
}
.sl-feature-typo .sl-row-link:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 4px;
    border-radius: 4px;
}
.sl-feature-typo .sl-row-title,
.sl-feature-typo .sl-row-arrow {
    transition: color 0.35s ease, transform 0.35s cubic-bezier(0.165, 0.84, 0.44, 1), opacity 0.35s ease;
}
.sl-feature-typo .sl-row-arrow {
    opacity: 0;
}
.sl-feature-typo .sl-typo-media {
    width: 100%;
    max-width: 350px;
    aspect-ratio: 16 / 10;
    margin-top: 1rem;
    position: relative;
}
@media (hover: hover) and (min-width: 1200px) {
    .sl-feature-typo .sl-typo-row:hover .sl-row-title,
    .sl-feature-typo .sl-typo-row:focus-within .sl-row-title {
        color: var(--smartlearn-primary);
        transform: translateX(20px);
    }
    .sl-feature-typo .sl-typo-row:hover .sl-row-arrow,
    .sl-feature-typo .sl-typo-row:focus-within .sl-row-arrow {
        opacity: 1;
        transform: translateX(10px);
    }
    .sl-feature-typo .sl-typo-media {
        position: absolute;
        top: 50%;
        inset-inline-end: 26%;
        width: 320px;
        height: 200px;
        margin-top: 0;
        z-index: 3;
        opacity: 0;
        transform: translateY(-50%) scale(0.95);
        transition: opacity 0.35s ease, transform 0.35s ease;
    }
    .sl-feature-typo .sl-typo-row:hover .sl-typo-media,
    .sl-feature-typo .sl-typo-row:focus-within .sl-typo-media {
        opacity: 1;
        transform: translateY(-50%) scale(1);
    }
}
[dir="rtl"] .sl-feature-typo .sl-row-arrow {
    transform: scaleX(-1);
}
@media (hover: hover) and (min-width: 1200px) {
    [dir="rtl"] .sl-feature-typo .sl-typo-row:hover .sl-row-title,
    [dir="rtl"] .sl-feature-typo .sl-typo-row:focus-within .sl-row-title {
        transform: translateX(-20px);
    }
    [dir="rtl"] .sl-feature-typo .sl-typo-row:hover .sl-row-arrow,
    [dir="rtl"] .sl-feature-typo .sl-typo-row:focus-within .sl-row-arrow {
        transform: scaleX(-1) translateX(10px);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-typo .sl-row-title,
    .sl-feature-typo .sl-row-arrow,
    .sl-feature-typo .sl-typo-media {
        transition: none;
    }
    .sl-feature-typo .sl-typo-row:hover .sl-row-title,
    .sl-feature-typo .sl-typo-row:focus-within .sl-row-title,
    .sl-feature-typo .sl-typo-row:hover .sl-row-arrow,
    .sl-feature-typo .sl-typo-row:focus-within .sl-row-arrow {
        transform: none;
    }
}
